import sys
import subprocess
import threading
import queue
import argparse
from typing import List, Tuple, Optional

def evaluate_expression(expr: str) -> int:
    try:
        return eval(expr)
    except:
        return -1

def run_command(args: List[str], value: int) -> Tuple[int, str]:
    cmd = args.copy()
    cmd.append(str(value))
    try:
        process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        exit_code = process.returncode
        stdout_text = stdout.decode('utf-8').rstrip('\n').replace('\n', '\\n')
        return exit_code, stdout_text
    except Exception:
        return -1, ""

def worker(job_queue: queue.Queue, results: queue.Queue, max_jobs: int):
    active_jobs = 0
    while True:
        job = job_queue.get()
        if job is None:
            job_queue.task_done()
            break
        if active_jobs < max_jobs:
            active_jobs += 1
            try:
                exit_code, stdout_text = run_command(job['args'], job['value'])
                results.put((job['expr'], exit_code, stdout_text))
            except:
                results.put((job['expr'], -1, ""))
            finally:
                active_jobs -= 1
                job_queue.task_done()
        else:
            job_queue.task_done()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--jobs', type=int, default=4)
    parser.add_argument('--', nargs=argparse.REMAINDER)
    args = parser.parse_args()

    if not args['']:
        sys.stderr.write("Error: No command specified after --\n")
        sys.exit(1)

    expr_queue = queue.Queue()
    results_queue = queue.Queue()
    threads = []

    for expr in sys.stdin:
        expr = expr.strip()
        if expr:
            value = evaluate_expression(expr)
            expr_queue.put({'expr': expr, 'value': value, 'args': args['']})

    max_jobs = args.jobs
    for _ in range(max_jobs):
        thread = threading.Thread(target=worker, args=(expr_queue, results_queue, max_jobs))
        thread.start()
        threads.append(thread)

    expr_queue.join()
    for _ in range(max_jobs):
        expr_queue.put(None)

    for thread in threads:
        thread.join()

    results = []
    while not results_queue.empty():
        results.append(results_queue.get())

    for expr, exit_code, stdout_text in results:
        print(f"{expr}\t{expr_queue.get()['value']}\t{exit_code}\t{stdout_text}")

if __name__ == "__main__":
    main()

import sys
import subprocess
import re
import concurrent.futures
import argparse

def evaluate_expression(expr):
    try:
        return int(eval(expr))
    except:
        return -1

def process_expression(expr, command_args):
    value = evaluate_expression(expr)
    if value == -1:
        return (expr, -1, "")
    cmd = command_args.copy()
    cmd.append(str(value))
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=False)
        return (expr, result.returncode, result.stdout.replace('\n', '\\n').strip())
    except:
        return (expr, -1, "")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--jobs', type=int, default=4)
    parser.add_argument('--', nargs=argparse.REMAINDER)
    args = parser.parse_args()

    if not args['']:
        print("Error: No command specified after --", file=sys.stderr)
        sys.exit(1)

    expressions = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            expressions.append(line)

    with concurrent.futures.ThreadPoolExecutor(max_workers=args.jobs) as executor:
        futures = []
        for expr in expressions:
            futures.append(executor.submit(process_expression, expr, args['']))

        results = []
        for future in concurrent.futures.as_completed(futures):
            results.append(future.result())

    results.sort(key=lambda x: expressions.index(x[0]))
    for expr, exit_code, stdout in results:
        print(f"{expr}\t{expr if exit_code == -1 else str(evaluate_expression(expr))}\t{exit_code}\t{stdout}")

if __name__ == "__main__":
    main()

import sys
import subprocess
import threading
import queue
import argparse
from collections import deque

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('--jobs', type=int, default=4)
    parser.add_argument('--', nargs=argparse.REMAINDER)
    return parser.parse_args()

def evaluate_expression(expr):
    try:
        return int(eval(expr))
    except:
        return -1

def process_expression(expr, cmd_args, result_queue):
    value = evaluate_expression(expr)
    if value == -1:
        result_queue.put((expr, -1, "", ""))
        return

    cmd = cmd_args[0]
    args = cmd_args[1:]
    full_cmd = [cmd] + args + [str(value)]

    try:
        process = subprocess.Popen(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        exit_code = process.returncode
        stdout_text = stdout.decode('utf-8').rstrip('\n').replace('\n', '\\n')
        stderr_text = stderr.decode('utf-8').rstrip('\n').replace('\n', '\\n')
        result_queue.put((expr, value, exit_code, stdout_text + stderr_text))
    except Exception:
        result_queue.put((expr, -1, -1, ""))

def main():
    args = parse_args()
    input_lines = [line.strip() for line in sys.stdin if line.strip()]
    input_queue = deque(input_lines)
    result_queue = queue.Queue()
    threads = []

    for _ in range(args.jobs):
        thread = threading.Thread(target=lambda: process_expression(input_queue.popleft(), args, result_queue))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    while not result_queue.empty():
        expr, value, exit_code, output = result_queue.get()
        print(f"{expr}\t{value}\t{exit_code}\t{output}")

if __name__ == "__main__":
    main()

import sys
import subprocess
import threading
import queue
import argparse
from concurrent.futures import ThreadPoolExecutor

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('--jobs', type=int, default=4)
    parser.add_argument('--', nargs=argparse.REMAINDER)
    return parser.parse_args()

def evaluate_expression(expr):
    try:
        return int(eval(expr))
    except:
        return -1

def run_command(expr, cmd_args):
    try:
        process = subprocess.Popen(cmd_args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        exit_code = process.returncode
        return exit_code, stdout.decode('utf-8').replace('\n', '\\n')
    except:
        return -1, ""

def process_input(input_lines, cmd_args):
    results = []
    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = []
        for expr in input_lines:
            value = evaluate_expression(expr)
            if value != -1:
                futures.append(executor.submit(run_command, expr, cmd_args))
        for future in futures:
            exit_code, stdout_text = future.result()
            results.append((expr.strip(), value, exit_code, stdout_text))
    return results

def main():
    args = parse_args()
    if not args['--']:
        print("Error: No command specified after --", file=sys.stderr)
        sys.exit(1)

    input_lines = [line.strip() for line in sys.stdin if line.strip()]
    if not input_lines:
        return

    cmd_args = list(args['--'])
    results = process_input(input_lines, cmd_args)

    for expr, value, exit_code, stdout_text in results:
        print(f"{expr}\t{value}\t{exit_code}\t{stdout_text}")

if __name__ == "__main__":
    main()
